334		} {
335			if qr := mustQuery(t, store, line); len(qr.Series) != 0 {
336				t.Fatalf("%s = %+v, want empty series array", line, qr.Series)
337			}
338		}
339		atEnd := queryOne(t, store, queryLabels("cpu", 5000, 5000, map[string]string{"zone": "out"}))
340		if atEnd.Count != 1 || atEnd.Average != 42 {
341			t.Fatalf("closed-range endpoint query = %+v, want count=1 average=42", atEnd)
342		}
343	}
344	
345	// labelOf 在规范序列表中按身份签名找回完整标签集合。
346	func labelOf(specs []identitySpec, sig string) map[string]string {
347		for _, sp := range specs {
348			if identitySig(sp.name, sp.labels) == sig {
349				return sp.labels
350			}
351		}
352		return nil
353	}
354	
355	// jsonStringEscaped 与 sample 的编码同义，但允许把指定字符写成合法的 \uXXXX
356	// 转义（逗号、等号、引号、反斜杠、中文等），解析后仍是原字符串；标签按按键
357	// 排序的逆序输出，制造与“直接书写+正序”完全不同的词法写法。
358	func jsonStringEscaped(s string, escape func(rune) bool) string {
359		var b strings.Builder
360		b.WriteByte('"')
361		for _, r := range s {
362			switch {
363			case escape(r):
364				fmt.Fprintf(&b, `\u%04x`, r)
365			case r == '"':
366				b.WriteString(`\"`)
367			case r == '\\':
368				b.WriteString(`\\`)
369			case r == '\n':
370				b.WriteString(`\n`)
371			case r < 0x20:
372				fmt.Fprintf(&b, `\u%04x`, r)
373			default:
374				b.WriteRune(r)
375			}
376		}
377		b.WriteByte('"')
378		return b.String()
379	}
380	
381	// escapedSample 构造一个采样点：名称与标签值里的指定字符以 \uXXXX 书写，
382	// 标签按键排序后逆序书写；解析后身份与直接书写完全一致。
383	func escapedSample(sp identitySpec, escape func(rune) bool) string {
384		var b strings.Builder
385		fmt.Fprintf(&b, `{"name":%s,"timestamp":%d,"value":%v`,
386			jsonStringEscaped(sp.name, escape), sp.ts, sp.value)
387		if sp.labels != nil {
388			keys := sortedKeys(sp.labels)
389			b.WriteString(`,"labels":{`)
390			for i := len(keys) - 1; i >= 0; i-- {
391				if i != len(keys)-1 {
392					b.WriteByte(',')
393				}
394				k := keys[i]
395				b.WriteString(jsonStringEscaped(k, escape))
396				b.WriteByte(':')
397				b.WriteString(jsonStringEscaped(sp.labels[k], escape))
398			}
399			b.WriteString(`}`)
400		}
401		b.WriteByte('}')
402		return b.String()
403	}
404	
405	// TestOrderingSameWhetherLiteralOrJSONEscaped：同一身份直接书写，或把逗号、等号、
406	// 引号、反斜杠、中文写成合法 JSON 字符转义并打乱标签书写顺序，得到的快照排列、
407	// 查询排列与每条统计值必须一致；冲突原因中为看清身份加的引号/转义文字不影响
408	// 身份与排序，结构化冲突仍指向解析后的真实标签。
409	func TestOrderingSameWhetherLiteralOrJSONEscaped(t *testing.T) {
410		specs := orderingSpecs()
411		escape := func(r rune) bool { return strings.ContainsRune(`,="\中`, r) }
412	
413		literal := NewMetricStore()
414		mustOK(t, literal, orderingBatch(specs))
415		mustOK(t, literal, "["+strings.Join([]string{
416			sample("cpu", 300, 10, map[string]string{"a": "2"}),
417			sample("cpu", 150, 13, map[string]string{"a": `2,b="x"`}),
418			sample("cpu", 5000, 42, map[string]string{"zone": "out"}),
419		}, ",")+"]")
420	
421		encoded := NewMetricStore()
422		shuffled := permutedSpecs(specs, shuffledOrderingPerm)
423		parts := make([]string, len(shuffled))
424		for i, sp := range shuffled {
425			parts[i] = escapedSample(sp, escape)
426		}
427		mustOK(t, encoded, "["+strings.Join(parts, ",")+"]")
428		mustOK(t, encoded, "["+strings.Join([]string{
429			escapedSample(identitySpec{name: "cpu", labels: map[string]string{"a": `2,b="x"`}, ts: 150, value: 13}, escape),
430			escapedSample(identitySpec{name: "cpu", labels: map[string]string{"zone": "out"}, ts: 5000, value: 42}, escape),
431			escapedSample(identitySpec{name: "cpu", labels: map[string]string{"a": "2"}, ts: 300, value: 10}, escape),
432		}, ",")+"]")
433	
434		// 两份数据经不同写法提交，全量快照身份排列与逐序列采样点逐一相同。
435		litSnap := mustOK(t, literal, `[]`)
436		encSnap := mustOK(t, encoded, `[]`)
437		if !reflect.DeepEqual(snapshotIdentitySigs(litSnap), snapshotIdentitySigs(encSnap)) {
438			t.Fatalf("snapshot order differs: literal %v vs escaped %v",
439				snapshotIdentitySigs(litSnap), snapshotIdentitySigs(encSnap))
440		}
441		if !reflect.DeepEqual(litSnap.Series, encSnap.Series) {
442			t.Fatalf("snapshots differ beyond ordering: %+v vs %+v", litSnap.Series, encSnap.Series)
443		}
444	
445		// 全量查询与子集+区间过滤查询（含只命中区间外点的空结果）在两种写法下结构相同。
446		for _, q := range []string{
447			queryAll("cpu", 0, 5000),
448			queryLabels("cpu", 0, 2000, map[string]string{"a": "2"}),
449			queryLabels("cpu", 0, 2000, map[string]string{"b": ""}),
450			queryLabels("cpu", 0, 2000, map[string]string{"k": "中"}),
451			queryLabels("cpu", 2001, 4999, map[string]string{"a": "2"}),
452			queryLabels("指标", 0, 5000, map[string]string{"k": "v"}),
453		} {
454			lr := mustQuery(t, literal, q)
455			er := mustQuery(t, encoded, q)
456			if !reflect.DeepEqual(lr, er) {
457				t.Fatalf("query %s differs between literal and escaped stores:\n%+v\n%+v", q, lr, er)
458			}
459		}
460	
461		// 以转义+逆序写法重提两个既有同点同值（一个含中文双标签、一个含空值标签）：
462		// 仍是重复采样，不新增点，排列不变。
463		dup := mustOK(t, encoded, "["+strings.Join([]string{
464			escapedSample(identitySpec{name: "cpu", labels: map[string]string{"k": "中", "z": "v"}, ts: 117, value: 18}, escape),
465			escapedSample(identitySpec{name: "cpu", labels: map[string]string{"aa": "1", "b": ""}, ts: 110, value: 11}, escape),
466		}, ",")+"]")
467		if dup.Added != 0 || dup.Duplicates != 2 {
468			t.Fatalf("escaped resubmit = added %d duplicates %d, want 0/2", dup.Added, dup.Duplicates)
469		}
470		if got := snapshotIdentitySigs(dup); !reflect.DeepEqual(got, wantSigs(specs)) {
471			t.Fatalf("order changed after escaped duplicates: %v", got)
472		}
473	
474		// 以转义写法对引号值序列提交不同数值：整批冲突拒绝，结构化身份是解析后的
475		// 真实标签 {k:"}（不是渲染文本 k="\""），原因文本中的引号只为可辨识，
476		// 不改变排序依据的身份。
477		lerr := mustFail(t, encoded,
478			"["+escapedSample(identitySpec{name: "cpu", labels: map[string]string{"k": `"`}, ts: 113, value: 999}, escape)+"]")
479		if lerr.Conflict == nil || lerr.Conflict.Existing != 14 || lerr.Conflict.Submitted != 999 {
480			t.Fatalf("escaped conflict detail = %+v", lerr.Conflict)
481		}
482		if !reflect.DeepEqual(lerr.Conflict.Series.Labels, map[string]string{"k": `"`}) {
483			t.Fatalf("escaped conflict labels = %v, want parsed {k:\"}", lerr.Conflict.Series.Labels)
484		}
485		if !strings.Contains(lerr.Error, `series cpu{k="\""} at timestamp 113`) {
486			t.Fatalf("escaped conflict message = %q", lerr.Error)
487		}
488		// 冲突拒绝不改变事实与排列。
489		if got := mustQuery(t, encoded, queryLabels("cpu", 113, 113, map[string]string{"k": `"`})); got.Series[0].Average != 14 {
490			t.Fatalf("value changed after rejected conflict batch: %+v", got.Series)
491		}
492	}
