195	// TestRunIngestSegmentationInvariantWritesAndQueries 是核心回归场景：
196	// 同一序列先后写入 ts=1000 值 2、ts=2000 值 4，再等值重复其中一点（计 1 次
197	// 重复），随后查询覆盖两个点的闭区间，应得到 count=2、average=3；中间穿插
198	// 空白行（只占行号）。该脚本在各种分段方式下输出与退出码必须逐条相同。
199	func TestRunIngestSegmentationInvariantWritesAndQueries(t *testing.T) {
200		lines := []string{
201			`[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`, // 行 1
202			``, // 行 2：空白行，无结果但占行号
203			`{"op":"query","name":"cpu","start":1000,"end":1000,"labels":{"host":"a"}}`, // 行 3
204			`[{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}}]`,         // 行 4
205			`   `, // 行 5：空白行
206			`[{"name":"cpu","timestamp":1000,"value":2.0,"labels":{"host":"a"}}]`,       // 行 6：等值重复
207			`{"op":"query","name":"cpu","start":1000,"end":2000,"labels":{"host":"a"}}`, // 行 7
208			`{"op":"query","name":"cpu","start":1000,"end":2000}`,                       // 行 8：省略标签
209		}
210		data := []byte(strings.Join(lines, "\n") + "\n")
211	
212		baseCode, baseRes := baselineResults(t, data)
213		if baseCode != 0 {
214			t.Fatalf("baseline exit code = %d, want 0", baseCode)
215		}
216		if len(baseRes) != 6 {
217			t.Fatalf("baseline got %d results, want 6 (3 writes + 3 queries)", len(baseRes))
218		}
219		// 行 1：added=1。
220		if baseRes[0]["status"] != "ok" || baseRes[0]["added"].(float64) != 1 {
221			t.Fatalf("baseline result 0 = %s", mustJSON(baseRes[0]))
222		}
223		// 行 3：单点查询 avg=2。
224		q := baseRes[1]["series"].([]interface{})
225		if len(q) != 1 || q[0].(map[string]interface{})["average"].(float64) != 2 {
226			t.Fatalf("baseline ts=1000 query = %s", mustJSON(baseRes[1]))
227		}
228		// 行 4：added=1。
229		if baseRes[2]["added"].(float64) != 1 {
230			t.Fatalf("baseline result 2 = %s", mustJSON(baseRes[2]))
231		}
232		// 行 6：同序列同时间戳等值（2 == 2.0）写入算重复，added=0 duplicates=1。
233		if baseRes[3]["added"].(float64) != 0 || baseRes[3]["duplicates"].(float64) != 1 {
234			t.Fatalf("baseline duplicate line = %s, want added=0 duplicates=1", mustJSON(baseRes[3]))
235		}
236		// 行 7：闭区间覆盖两个点，count=2 average=(2+4)/2=3。
237		q = baseRes[4]["series"].([]interface{})
238		if len(q) != 1 {
239			t.Fatalf("baseline range query series = %s", mustJSON(baseRes[4]))
240		}
241		s := q[0].(map[string]interface{})
242		if s["count"].(float64) != 2 || s["average"].(float64) != 3 {
243			t.Fatalf("baseline range query = %s, want count=2 average=3", mustJSON(s))
244		}
245		// 行 8：不带标签的同名查询命中同一条序列。
246		q = baseRes[5]["series"].([]interface{})
247		if len(q) != 1 || q[0].(map[string]interface{})["count"].(float64) != 2 {
248			t.Fatalf("baseline unlabeled query = %s", mustJSON(baseRes[5]))
249		}
250	
251		for _, v := range segmentationVariants(data) {
252			v := v
253			t.Run(v.label, func(t *testing.T) {
254				assertMatchesBaseline(t, v.label, v.in, baseCode, baseRes)
255			})
256		}
257	}
