259	// TestRunIngestSegmentationInvariantWithFailures 确认在含失败行（解析失败、
260	// 冲突、非零退出）的输入上，分段同样不改变任何结果与最终退出状态：失败行
261	// 的行号、index/conflict，以及后续成功行都与整份到达时一致。
262	func TestRunIngestSegmentationInvariantWithFailures(t *testing.T) {
263		lines := []string{
264			`[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`, // 行 1 成功
265			`not json`, // 行 2 整行解析失败，无 index
266			``,         // 行 3 空白
267			`[{"name":"cpu","timestamp":1000,"value":4,"labels":{"host":"a"}}]`, // 行 4 冲突
268			`   `, // 行 5 空白
269			`[]`,  // 行 6 空批成功，快照仍只有行 1
270			`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`, // 行 7
271		}
272		data := []byte(strings.Join(lines, "\n") + "\n")
273	
274		baseCode, baseRes := baselineResults(t, data)
275		if baseCode == 0 {
276			t.Fatalf("baseline exit code = 0, want non-zero")
277		}
278		for _, v := range segmentationVariants(data) {
279			v := v
280			t.Run(v.label, func(t *testing.T) {
281				assertMatchesBaseline(t, v.label, v.in, baseCode, baseRes)
282			})
283		}
284		if got := baseRes[1]; got["status"] != "error" || int(got["line"].(float64)) != 2 {
285			t.Fatalf("baseline parse error = %s", mustJSON(got))
286		}
287		if _, has := baseRes[1]["index"]; has {
288			t.Fatalf("parse error must not carry index: %s", mustJSON(baseRes[1]))
289		}
290		if got := baseRes[2]; got["status"] != "error" || int(got["line"].(float64)) != 4 ||
291			int(got["index"].(float64)) != 1 {
292			t.Fatalf("baseline conflict = %s", mustJSON(got))
293		}
294		if baseRes[4]["series"].([]interface{})[0].(map[string]interface{})["count"].(float64) != 1 {
295			t.Fatalf("baseline query must see only the committed point: %s", mustJSON(baseRes[4]))
296		}
297	}
