299	// TestRunIngestMultibyteTextSurvivesFragmentation 覆盖中文（3 字节/字）与
300	// 补充平面字符（4 字节/字，如 U+1F600 😀）跨片段送达：一个 UTF-8 字符的字节
301	// 可以分开到达。完整输入合法时，输出必须保留还原后的真实名称与完整标签，
302	// 不得因分段出现字符替换（U+FFFD）、丢失或意外产生另一条序列。
303	func TestRunIngestMultibyteTextSurvivesFragmentation(t *testing.T) {
304		name := "指标😀"
305		labelKey := "机房😀"
306		labelVal := "北京😀"
307		writeLine := `[{"name":"` + name + `","timestamp":1,"value":1,"labels":{` +
308			`"` + labelKey + `":"` + labelVal + `"}}]`
309		queryLine := `{"op":"query","name":"` + name + `","start":0,"end":10,"labels":{` +
310			`"` + labelKey + `":"` + labelVal + `"}}`
311		data := []byte(writeLine + "\n" + queryLine + "\n")
312	
313		// 收集落在多字节字符内部的字节边界：续字节（10xxxxxx）所在偏移处切开，
314		// 必然把某个 UTF-8 字符的字节分开。
315		var internalCuts []int
316		for i := 1; i < len(data); i++ {
317			if data[i]&0xC0 == 0x80 {
318				internalCuts = append(internalCuts, i)
319			}
320		}
321		if len(internalCuts) == 0 {
322			t.Fatal("test setup: expected multibyte characters to split")
323		}
324	
325		checkRealIdentity := func(t *testing.T, res []map[string]interface{}) {
326			t.Helper()
327			if len(res) != 2 {
328				t.Fatalf("%d results, want 2: %s", len(res), mustJSON(res))
329			}
330			arr := res[0]["series"].([]interface{})
331			if len(arr) != 1 {
332				t.Fatalf("series = %s, want exactly 1 (no accidental extra series)", mustJSON(arr))
333			}
334			s := arr[0].(map[string]interface{})
335			if s["name"] != name {
336				t.Fatalf("name = %q, want %q (no replacement/loss)", s["name"], name)
337			}
338			if !reflect.DeepEqual(s["labels"], map[string]interface{}{labelKey: labelVal}) {
339				t.Fatalf("labels = %s, want the full real labels", mustJSON(s["labels"]))
340			}
341			q := res[1]["series"].([]interface{})
342			if len(q) != 1 {
343				t.Fatalf("query = %s, want exactly 1 match", mustJSON(res[1]))
344			}
345			q0 := q[0].(map[string]interface{})
346			if q0["name"] != name {
347				t.Fatalf("query name = %q, want %q", q0["name"], name)
348			}
349			if !reflect.DeepEqual(q0["labels"],
350				map[string]interface{}{labelKey: labelVal}) {
351				t.Fatalf("query labels = %s", mustJSON(q0))
352			}
353		}
354	
355		_, baseRes := baselineResults(t, data)
356		checkRealIdentity(t, baseRes)
357	
358		// 每个多字节字符内部边界单独切开（前后各一整段）。
359		for _, d := range internalCuts {
360			d := d
361			t.Run("split-inside-char@"+strconv.Itoa(d), func(t *testing.T) {
362				_, res := runIngestForSegmentation(t, newSegmentedReader(data, d))
363				checkRealIdentity(t, res)
364			})
365		}
366		// 所有多字节字符同时在内部被切开，以及逐字节送达。
367		t.Run("split-inside-every-multibyte-char", func(t *testing.T) {
368			_, res := runIngestForSegmentation(t, newSegmentedReader(data, internalCuts...))
369			checkRealIdentity(t, res)
370		})
371		t.Run("1-byte", func(t *testing.T) {
372			_, res := runIngestForSegmentation(t, segments1Byte(data))
373			checkRealIdentity(t, res)
374		})
375	}
